/**
 * Display-block authoring types — the typed shapes an author places in
 * `app({ displayBlocks: {...} })` (record-view layout) and
 * `app({ recordCreateDisplayBlocks: {...} })` (new-record form).
 *
 * A display block controls how a record's fields and components are
 * laid out in the UI. Each bag is keyed by an author-chosen handle;
 * each entry is a discriminated variant keyed on `kind`. The platform
 * stores all variant data inside one JSON `properties` column plus a
 * few flat columns (`fieldId`, `stageId`, parent linkage); the
 * serializer translates these typed shapes into that wire form, and
 * the deserializer inverts it.
 *
 * Two structural rules mirror the platform:
 *   - **Children-on-parent.** A `group` block lists its child blocks
 *     by bag key in `blocks: ["title", "status"]`. Children stay at
 *     the top level of the bag (no `parent` slot); the serializer
 *     wires the parent linkage from the group's `blocks` list.
 *   - **Stage scoping is top-level only.** `stage` is honored on
 *     top-level bag entries; a group's children inherit the group's
 *     stage. Omit `stage` for the default (unstaged) layout.
 */
import type { AppField, AppStage } from "./app.js";
/** Where a block renders within the record layout. */
export type DisplayBlockLocation = "CENTER" | "RIGHT";
/**
 * Comments channel. Today the platform exposes a single channel
 * (`CONSUMER`); modeled as a union so new channels are additive.
 */
export type CommentsChannel = "CONSUMER";
/**
 * Shared slots on every display-block variant. Per-variant interfaces
 * extend this with their specific fields.
 */
interface DisplayBlockCommon {
    /**
     * Server-assigned block id. Stamped on pulled blocks so a re-deploy
     * updates the existing block in place instead of creating a
     * duplicate. Hand-authored blocks omit it — the platform assigns one.
     */
    readonly id?: string;
    /** Hide the block without removing it. */
    readonly hidden?: boolean;
    /** Which column the block renders in. */
    readonly displayLocation?: DisplayBlockLocation;
    /**
     * Workflow stage this block is scoped to. Only honored on top-level
     * bag entries — a group's children inherit the group's stage. Omit
     * for the default (unstaged) layout.
     */
    readonly stage?: AppStage;
}
/**
 * A layout container. Groups hold other blocks (referenced by bag key
 * in `blocks`) and are the only blocks that can surface as a side-nav
 * entry.
 */
export interface GroupDisplayBlock extends DisplayBlockCommon {
    readonly kind: "group";
    readonly name: string;
    readonly color?: string;
    readonly icon?: string;
    /** Max layout columns the group renders its children across. */
    readonly maxColumns?: number;
    /** Surface this group as a left-nav entry. */
    readonly sideNavItem?: boolean;
    /** Bag keys of the child blocks nested under this group, in order. */
    readonly blocks?: readonly string[];
}
/** Renders a single aspect field. */
export interface FieldDisplayBlock extends DisplayBlockCommon {
    readonly kind: "field";
    /** Typed reference to the field this block renders. */
    readonly field: AppField;
}
/** Renders a custom display widget. */
export interface WidgetDisplayBlock extends DisplayBlockCommon {
    readonly kind: "widget";
    /** Display-widget id. No typed widget ref in the EDK yet. */
    readonly widget: string;
}
/** The comments section. */
export interface CommentsDisplayBlock extends DisplayBlockCommon {
    readonly kind: "comments";
    /** Channels the comments section exposes. */
    readonly channels?: readonly CommentsChannel[];
    /** Optional per-channel display name override. */
    readonly channelNames?: Partial<Record<CommentsChannel, string>>;
}
/** The attachments section. */
export interface AttachmentDisplayBlock extends DisplayBlockCommon {
    readonly kind: "attachment";
}
/** The activity-log section. */
export interface ActivityLogDisplayBlock extends DisplayBlockCommon {
    readonly kind: "activityLog";
}
/** The status section. */
export interface StatusDisplayBlock extends DisplayBlockCommon {
    readonly kind: "status";
}
/** The related-items section. */
export interface RelatedItemsDisplayBlock extends DisplayBlockCommon {
    readonly kind: "relatedItems";
}
/** The related-tasks section. */
export interface RelatedTasksDisplayBlock extends DisplayBlockCommon {
    readonly kind: "relatedTasks";
}
/** The approvals section. */
export interface ApprovalsDisplayBlock extends DisplayBlockCommon {
    readonly kind: "approvals";
}
/**
 * The surveys section. `stageOwners` (per-stage survey ownership) is a
 * richer structure not yet modeled — it round-trips opaquely through
 * the serializer but isn't author-editable today.
 */
export interface SurveysDisplayBlock extends DisplayBlockCommon {
    readonly kind: "surveys";
}
/**
 * The related-create section (deprecated on the platform; kept for
 * round-trip completeness).
 */
export interface RelatedCreateDisplayBlock extends DisplayBlockCommon {
    readonly kind: "relatedCreate";
    readonly name: string;
}
/**
 * One display block in either bag. Discriminated on `kind`.
 */
export type DisplayBlock = GroupDisplayBlock | FieldDisplayBlock | WidgetDisplayBlock | CommentsDisplayBlock | AttachmentDisplayBlock | ActivityLogDisplayBlock | StatusDisplayBlock | RelatedItemsDisplayBlock | RelatedTasksDisplayBlock | ApprovalsDisplayBlock | SurveysDisplayBlock | RelatedCreateDisplayBlock;
/** A keyed bag of display blocks, mirroring the `fields` bag shape. */
export type DisplayBlockBag = Readonly<Record<string, DisplayBlock>>;
/**
 * The `kind` discriminator → platform `DisplayBlockType` enum value.
 * The serializer stamps the enum into each block's `properties.type`.
 */
export declare const DISPLAY_BLOCK_KIND_TO_TYPE: Readonly<Record<DisplayBlock["kind"], string>>;
/**
 * Read-side GraphQL `__typename` → `kind`. The pull response
 * discriminates blocks by their concrete GraphQL type name
 * (`AspectCommentsDisplayBlock`, …), NOT by the `DisplayBlockType`
 * enum the write side stamps into `properties.type` — so the
 * deserializer keys off this map, not {@link DISPLAY_BLOCK_KIND_TO_TYPE}.
 */
export declare const DISPLAY_BLOCK_TYPENAME_TO_KIND: Readonly<Record<string, DisplayBlock["kind"]>>;
export {};
